from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove spaces from the input string
    groups = []  # Initialize list to store separate groups of parentheses
    current_group = ""  # Initialize variable to store current group of parentheses

    for char in paren_string:
        if char == "(":
            if current_group:
                groups.append(current_group)
            current_group = "("
        elif char == ")":
            current_group += ")"
            groups.append(current_group)
            current_group = ""

    return groups

